import{_ as a,o,c as r,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const s=JSON.parse('{"title":"Characterizing Crc Operation on Ceph - Rixin Luo, Huawei Technologies Co., Ltd","description":"","frontmatter":{"title":"Characterizing Crc Operation on Ceph - Rixin Luo, Huawei Technologies Co., Ltd","date":"2025-01-23T00:00:00.000Z","updated":"2025-01-24T00:00:00.000Z","tags":["Ceph","CRC","Performance Optimization","Bluestore","Data Integrity"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Characterizing_Crc_Operation_on_Ceph_-_Rixin_Luo_Huawei_Technologies_Co._Ltd.md","filePath":"posts/2025/Characterizing_Crc_Operation_on_Ceph_-_Rixin_Luo_Huawei_Technologies_Co._Ltd.md","lastUpdated":1780459816000}'),t={name:"posts/2025/Characterizing_Crc_Operation_on_Ceph_-_Rixin_Luo_Huawei_Technologies_Co._Ltd.md"};function c(C,e,l,h,n,_){return o(),r("div",null,[...e[0]||(e[0]=[i('<p>本会议纪要详细描述了关于Ceph中循环冗余校验（CRC）操作的分析与优化。以下是对会议内容的总结：</p><h3 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h3><p>Ceph 操作中的循环冗余校验（CRC）分析与优化</p><h3 id="会议内容总结" tabindex="-1">会议内容总结 <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结&quot;">​</a></h3><h4 id="_1-crc-的重要性与背景" tabindex="-1">1. CRC 的重要性与背景 <a class="header-anchor" href="#_1-crc-的重要性与背景" aria-label="Permalink to &quot;1. CRC 的重要性与背景&quot;">​</a></h4><p>CRC用于检测数据错误，现代CPU提供指令加速CRC操作。在Ceph中，CRC操作占3%的CPU利用率，优化CRC有助于提升性能。</p><h4 id="_2-crc-操作的执行机制" tabindex="-1">2. CRC 操作的执行机制 <a class="header-anchor" href="#_2-crc-操作的执行机制" aria-label="Permalink to &quot;2. CRC 操作的执行机制&quot;">​</a></h4><p>CRC操作通过<code>m_worker</code>和<code>tpd_thread</code>两种策略执行。<code>m_worker</code>负责接收和发送消息，消息结构包括<code>Preamble</code>、<code>Payload</code>和<code>AppLog</code>。</p><h4 id="_3-bluestore-中的-crc-计算" tabindex="-1">3. Bluestore 中的 CRC 计算 <a class="header-anchor" href="#_3-bluestore-中的-crc-计算" aria-label="Permalink to &quot;3. Bluestore 中的 CRC 计算&quot;">​</a></h4><p>Bluestore在读写操作中计算CRC，确保数据正确性。相关配置参数影响CRC行为。</p><h4 id="_4-工作负载分析" tabindex="-1">4. 工作负载分析 <a class="header-anchor" href="#_4-工作负载分析" aria-label="Permalink to &quot;4. 工作负载分析&quot;">​</a></h4><p>使用<code>RBD</code>工作负载进行测试，测试了4KB和64KB读写操作，副本数为1和3。使用<code>BCC Trace</code>工具统计了<code>crc32c</code>函数调用次数。</p><h4 id="_5-crc-操作的分布分析" tabindex="-1">5. CRC 操作的分布分析 <a class="header-anchor" href="#_5-crc-操作的分布分析" aria-label="Permalink to &quot;5. CRC 操作的分布分析&quot;">​</a></h4><p>4KB读写操作中，小尺寸CRC操作占主导地位，约84%。64KB读写操作中，小尺寸CRC操作仍占50%左右。</p><h4 id="_6-副本操作的-crc-分析" tabindex="-1">6. 副本操作的 CRC 分析 <a class="header-anchor" href="#_6-副本操作的-crc-分析" aria-label="Permalink to &quot;6. 副本操作的 CRC 分析&quot;">​</a></h4><p>单副本和三副本读写操作中，小尺寸CRC操作占比较高。副本操作的回复消息占用了较多的CRC操作。</p><h4 id="_7-优化建议" tabindex="-1">7. 优化建议 <a class="header-anchor" href="#_7-优化建议" aria-label="Permalink to &quot;7. 优化建议&quot;">​</a></h4><ul><li>优化编码预处理，避免小尺寸CRC操作。</li><li>优化数据结构，提高CRC操作效率。</li><li>使用内联汇编优化<code>Preamble</code>消息头，提升性能约2%。</li><li>优化内存分配策略，提升CPU缓存效率。</li></ul><h4 id="决定事项与后续行动计划" tabindex="-1">决定事项与后续行动计划 <a class="header-anchor" href="#决定事项与后续行动计划" aria-label="Permalink to &quot;决定事项与后续行动计划&quot;">​</a></h4><ul><li>对Bluestore中的CRC操作进行优化，特别是针对小尺寸数据块的CRC计算。</li><li>性能测试与验证优化后的CRC操作效率。</li><li>开发团队根据优化建议进行代码实现，并集成到Ceph的主分支中。</li></ul><h3 id="会议结论" tabindex="-1">会议结论 <a class="header-anchor" href="#会议结论" aria-label="Permalink to &quot;会议结论&quot;">​</a></h3><p>通过优化CRC操作，可以有效提升Ceph的性能和数据完整性。开发团队将根据优化建议进行代码实现，并集成到Ceph的主分支中。</p>',22)])])}const p=a(t,[["render",c]]);export{s as __pageData,p as default};
